    maxconn=20,  # maximum number of connections to keep alive
    maxsize=100,  # maximum number of connections to reuse
    timeout=30  # timeout for connections
)

# Acquire a connection from the pool
conn = pool.getconn()

# Use the connection
cursor = conn.cursor()

# Release the connection back to the pool
conn.close()
```
